import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

type Copy = { annual: NonNullable<LocaleFollowup[string]>; monthly: NonNullable<LocaleFollowup[string]> };

// Copy describes the implemented 2026 scenario model, not a confirmed legal quote.
export const japanSalaryFollowups: Record<SupportedLocale, Copy> = {
  ko: {
    annual: { description: "일본 연봉을 연간 총지급액에서 모형상 세금·사회보험료를 뺀 값으로 추정하고 월평균도 보여줍니다. 개인별 확정 실수령액은 아닙니다.", howTo: "연간 총지급액과 연령 구간(40세 미만/이상)을 선택하세요. 40세 이상이면 모형상 개호보험료가 더해집니다. 결과는 2026 정책 데이터에 설정된 가정에 따라 계산됩니다.", formula: "급여소득=연봉−급여소득공제. 과세소득은 급여소득에서 모형 사회보험료와 기본공제를 빼고 1,000엔 단위로 내림합니다. 소득세는 설정된 누진표와 부흥특별소득세 가산을 적용합니다. 주민세는 다음 연도 단순 추정이며, 연간 실수령=연봉−사회보험−소득세−주민세, 월평균=연간 실수령÷12입니다.", example: { question: "연봉 360만 엔, 40세 미만이면?", answer: "엔진 결과는 급여소득 244만 엔, 소득세 47,068엔, 다음 연도 주민세 추정 153,260엔, 사회보험 추정 527,400엔, 연간 실수령 2,872,272엔, 월평균 239,356엔입니다. 모형값이며 실제 급여명세서와 같다고 보장하지 않습니다." }, faq: { question: "왜 실제 일본 급여와 다를 수 있나요?", answer: "건강보험 5%는 편의상 가정이고 보험자·지역별 차이, 표준보수 상한, 상여, 부양·개인 공제, 지방별 주민세를 충분히 반영하지 않습니다. 2026 공제 일정의 적용 시점도 검증 중이므로 최신 법정액으로 사용하지 마세요." } },
    monthly: { description: "일본 월급을 12배 해 연간 모형 계산을 한 뒤 공제 항목과 실수령액을 월평균으로 나눠 보여줍니다. 실제 월별 급여명세서가 아닙니다.", howTo: "월간 총지급액과 연령 구간을 입력하세요. 엔진은 월급을 12배 해 연봉 계산을 적용한 뒤 각 결과를 12로 나눕니다. 상여는 별도로 입력하지 않으므로 포함되지 않습니다.", formula: "연 환산 총급여=월급×12. 연간 급여소득공제·보험·세금 모형을 적용하고, 월 표시값=각 연간 결과÷12를 엔 단위로 반올림합니다. 40세 이상 선택 시 모형 개호보험료가 연 소득에 추가됩니다.", example: { question: "월급 30만 엔, 40세 미만이면?", answer: "연 환산액은 360만 엔입니다. 엔진은 월평균 소득세 3,922엔, 주민세 12,772엔, 사회보험 43,950엔, 공제 합계 60,644엔, 월 실수령 추정 239,356엔을 표시합니다. 이는 연간 추정치를 나눈 값입니다." }, faq: { question: "상여나 실제 월별 변동이 반영되나요?", answer: "아니요. 입력 월급을 고정적으로 12개월 적용하며 상여, 월별 보험료 산정, 지역·부양·보험자별 조건은 계산하지 않습니다. 연봉 도구와 같은 연간 모형을 쓰므로 반올림 차이가 날 수 있습니다." } },
  },
  en: {
    annual: { description: "Estimates annual and average monthly Japanese take-home pay by subtracting modeled taxes and social insurance from gross annual salary. It is not an individualized payroll quote.", howTo: "Enter annual gross pay and choose under 40 or age 40+. The model adds its care-insurance proxy for the 40+ option and uses the configured 2026 scenario assumptions.", formula: "Employment income = salary − salary-income deduction. Taxable income subtracts modeled social insurance and the selected basic deduction, then floors to ¥1,000. Income tax uses the configured progressive bands plus reconstruction surtax. Resident tax is a simplified next-year estimate. Annual net = gross − social insurance − income tax − resident tax; monthly average = annual net ÷ 12.", example: { question: "What does ¥3,600,000 annual gross pay produce for someone under 40?", answer: "The engine returns ¥2,440,000 employment income, ¥47,068 modeled income tax, ¥153,260 estimated next-year resident tax, ¥527,400 modeled social insurance, ¥2,872,272 annual take-home and ¥239,356 monthly average. These are model outputs, not a guaranteed payslip." }, faq: { question: "Why can actual Japanese pay differ?", answer: "Health insurance is a 5% proxy; insurer/prefecture rates, contribution ceilings, bonuses, dependents and personal deductions, and municipal resident-tax differences are not fully modeled. Applicability dates for the configured 2026 deduction schedule remain under review, so do not treat this as a current legal determination." } },
    monthly: { description: "Annualizes a Japanese monthly salary, runs the annual scenario model, then displays each modeled deduction and take-home amount as a monthly average. It is not a month-specific payslip.", howTo: "Enter monthly gross pay and choose the age group. The engine multiplies salary by 12, applies the annual salary model, then divides its annual outputs by 12. Bonuses are not entered or included.", formula: "Annualized gross = monthly salary × 12. The model applies annual salary deductions, insurance and tax, then rounds each annual result ÷ 12 to whole yen. The 40+ option adds the model's care-insurance proxy to annual pay.", example: { question: "What does ¥300,000 monthly gross pay produce for someone under 40?", answer: "Annualized gross is ¥3,600,000. The engine displays average monthly income tax ¥3,922, resident tax ¥12,772, social insurance ¥43,950, total deductions ¥60,644 and modeled take-home ¥239,356. This is the annual estimate divided across 12 months." }, faq: { question: "Are bonuses or month-to-month changes included?", answer: "No. The entered monthly salary is assumed for all 12 months; bonuses, actual monthly contribution bases, regional rates, dependents and insurer-specific terms are not calculated. It shares the annual model, with whole-yen rounding." } },
  },
  ja: {
    annual: { description: "日本の年収からモデル上の税・社会保険料を差し引き、年間と月平均の手取り目安を示します。個別の確定給与計算ではありません。", howTo: "年間総支給額と年齢区分（40歳未満／以上）を入力します。40歳以上ではモデル上の介護保険料が加算されます。設定された2026年シナリオの前提を使用します。", formula: "給与所得=年収−給与所得控除。給与所得からモデル社会保険料と所得区分に応じた基礎控除を引き、課税所得を1,000円単位で切り捨てます。設定された累進税率と復興特別所得税を適用し、住民税は翌年度の簡易推定とします。年間手取り=年収−社会保険料−所得税−住民税、月平均=年間手取り÷12。", example: { question: "年収360万円、40歳未満の場合は？", answer: "エンジンは給与所得244万円、所得税47,068円、翌年度住民税推定153,260円、社会保険料推定527,400円、年間手取り2,872,272円、月平均239,356円を返します。モデル結果であり、実際の給与明細を保証しません。" }, faq: { question: "実際の日本の手取りと違うのはなぜですか？", answer: "健康保険料は5%の便宜的な仮定です。保険者・都道府県差、標準報酬上限、賞与、扶養・個人控除、自治体差を十分反映しません。2026年控除スケジュールの適用時期も確認中のため、現行法上の確定額として使わないでください。" } },
    monthly: { description: "日本の月給を12倍して年額モデルを計算し、各控除と手取りを月平均で表示します。特定月の給与明細ではありません。", howTo: "月間総支給額と年齢区分を入力します。月給を12倍して年収モデルに適用し、年間結果を12で割ります。賞与は入力欄がないため含まれません。", formula: "年換算総支給=月給×12。年額の給与控除・保険・税モデルを適用し、各項目を12で割って1円単位に丸めます。40歳以上ではモデル上の介護保険料を年額に加算します。", example: { question: "月給30万円、40歳未満の場合は？", answer: "年換算額は360万円です。月平均の所得税3,922円、住民税12,772円、社会保険料43,950円、控除合計60,644円、手取り目安239,356円を表示します。年額推定を12か月に配分した結果です。" }, faq: { question: "賞与や月ごとの変動も含まれますか？", answer: "いいえ。入力した月給が12か月続く前提で、賞与、月ごとの保険料算定、地域・扶養・保険者ごとの条件は計算しません。年収版と同じモデルを用い、円単位の丸め差が生じる場合があります。" } },
  },
  zh: {
    annual: { description: "从日本年薪中扣除模型估算的税费和社会保险，显示年度及月均到手金额；不是个人工资单的法定核算。", howTo: "输入年度税前工资并选择未满40岁或40岁以上。选择40岁以上时模型会加上护理保险估算，其他项目按配置的2026情景假设计算。", formula: "工资所得=年薪−工资所得扣除。再减去模型社会保险和对应所得档的基础扣除，课税所得向下取整至1,000日元。所得税按配置累进税档并加重建特别税；居民税为下一年度简化估算。年净额=年薪−社保−所得税−居民税；月均=年净额÷12。", example: { question: "未满40岁、年薪3,600,000日元时结果如何？", answer: "引擎返回工资所得2,440,000日元、模型所得税47,068日元、次年居民税估算153,260日元、模型社保527,400日元、年到手2,872,272日元、月均239,356日元。这是模型结果，不保证等于实际工资单。" }, faq: { question: "为何与日本实际到手工资不同？", answer: "健康保险按5%代理假设，未完整考虑保险机构和地区差异、缴费上限、奖金、扶养及个人扣除、地方居民税差异。2026扣除表的适用时间仍待核对，请勿将结果视为现行法定金额。" } },
    monthly: { description: "将日本月薪乘以12进行年度情景计算，再把各项估算扣款和到手额折算为月均值；不是某个月的工资单。", howTo: "输入月税前工资并选择年龄档。引擎先乘以12套用年薪模型，再将年结果除以12；没有单独输入奖金的选项，因此不计奖金。", formula: "年换算总薪资=月薪×12。应用年度工资扣除、保险与税费模型后，各年度金额除以12并四舍五入到日元。选择40岁以上时会增加模型护理保险估算。", example: { question: "未满40岁、月薪300,000日元时结果如何？", answer: "年换算总额为3,600,000日元。引擎显示月均所得税3,922日元、居民税12,772日元、社保43,950日元、扣款合计60,644日元、模型到手239,356日元。这是年估算平均分到12个月。" }, faq: { question: "奖金或每月变化会计入吗？", answer: "不会。假设该月薪连续支付12个月；不计算奖金、实际逐月缴费基数，以及地区、扶养或保险机构差异。它与年薪工具使用同一模型，日元取整可能带来小幅差异。" } },
  },
  es: {
    annual: { description: "Estima el neto anual y mensual medio en Japón restando impuestos y seguros sociales modelados del salario bruto anual. No es una liquidación individual oficial.", howTo: "Introduce el salario bruto anual y elige menor de 40 o 40 años o más. La segunda opción añade la aproximación del seguro de cuidados; se usan los supuestos configurados para el escenario de 2026.", formula: "Renta salarial = salario anual − deducción salarial. Se restan el seguro social modelado y la deducción básica correspondiente; la base imponible se redondea hacia abajo a 1.000 yenes. El impuesto sobre la renta usa los tramos progresivos configurados más el recargo de reconstrucción. El impuesto residencial es una estimación simplificada del año siguiente. Neto anual = bruto − seguro social − ambos impuestos; promedio mensual = neto anual ÷ 12.", example: { question: "¿Qué resultado da un salario anual de ¥3.600.000 para alguien menor de 40?", answer: "El motor devuelve renta salarial ¥2.440.000, impuesto modelado ¥47.068, impuesto residencial estimado del próximo año ¥153.260, seguro social modelado ¥527.400, neto anual ¥2.872.272 y promedio mensual ¥239.356. Es una salida del modelo, no una nómina garantizada." }, faq: { question: "¿Por qué puede diferir del neto real en Japón?", answer: "El seguro médico usa una hipótesis del 5%; no se modelan plenamente diferencias de aseguradora/región, topes de cotización, bonus, dependientes y deducciones personales ni variaciones municipales. La fecha aplicable de las deducciones de 2026 sigue pendiente de conciliación; no lo tomes como importe legal vigente." } },
    monthly: { description: "Anualiza el sueldo mensual japonés, aplica el modelo anual y presenta cada deducción y neto como promedio mensual. No representa una nómina de un mes concreto.", howTo: "Introduce el bruto mensual y elige el grupo de edad. El motor multiplica el sueldo por 12, aplica el modelo anual y divide sus resultados entre 12. No se introduce ni incluye el bonus.", formula: "Bruto anualizado = sueldo mensual × 12. Se aplican las deducciones salariales, seguros e impuestos anuales; cada resultado se divide entre 12 y se redondea al yen. La opción de 40 años o más añade la aproximación anual del seguro de cuidados.", example: { question: "¿Qué resultado da un sueldo bruto mensual de ¥300.000 para alguien menor de 40?", answer: "El bruto anualizado es ¥3.600.000. El motor muestra promedio mensual de impuesto sobre la renta ¥3.922, residencial ¥12.772, seguro social ¥43.950, deducciones totales ¥60.644 y neto modelado ¥239.356. Es la estimación anual repartida entre 12 meses." }, faq: { question: "¿Incluye bonus o cambios entre meses?", answer: "No. Supone que el sueldo indicado se paga durante los 12 meses; no calcula bonus, bases reales de cotización mensuales ni diferencias regionales, de dependientes o aseguradora. Comparte el modelo anual y puede haber diferencias por redondeo al yen." } },
  },
  "pt-br": {
    annual: { description: "Estima o líquido anual e a média mensal no Japão, subtraindo impostos e seguros sociais modelados do salário bruto anual. Não é uma folha individual oficial.", howTo: "Informe o salário bruto anual e escolha menos de 40 anos ou 40 anos ou mais. A segunda opção acrescenta a aproximação do seguro de cuidados; o cálculo usa as premissas configuradas para o cenário de 2026.", formula: "Renda do trabalho = salário anual − dedução salarial. Subtraem-se o seguro social modelado e a dedução básica da faixa; a base tributável é arredondada para baixo ao milhar de ienes. O imposto de renda usa as faixas progressivas configuradas e o adicional de reconstrução. O imposto residencial é uma estimativa simplificada do ano seguinte. Líquido anual = bruto − seguro social − os dois impostos; média mensal = líquido anual ÷ 12.", example: { question: "Qual o resultado para salário anual de ¥3.600.000 e idade abaixo de 40?", answer: "O motor retorna renda do trabalho de ¥2.440.000, imposto de renda modelado de ¥47.068, imposto residencial estimado para o próximo ano de ¥153.260, seguro social modelado de ¥527.400, líquido anual de ¥2.872.272 e média mensal de ¥239.356. É uma saída do modelo, não uma folha garantida." }, faq: { question: "Por que o valor real no Japão pode ser diferente?", answer: "O seguro de saúde usa uma hipótese de 5%; diferenças de seguradora/região, limites de contribuição, bônus, dependentes e deduções pessoais e variações municipais não são totalmente modeladas. A data de aplicação da tabela de deduções de 2026 ainda precisa ser reconciliada; não trate o resultado como valor legal vigente." } },
    monthly: { description: "Anualiza o salário mensal japonês, executa o modelo anual e mostra cada dedução e líquido como média mensal. Não representa a folha de um mês específico.", howTo: "Informe o salário bruto mensal e selecione a faixa etária. O motor multiplica por 12, aplica o modelo anual e divide os resultados por 12. Não há campo para bônus, que ficam fora do cálculo.", formula: "Bruto anualizado = salário mensal × 12. Aplicam-se as deduções salariais, seguros e impostos anuais; cada resultado é dividido por 12 e arredondado ao iene. A opção 40+ acrescenta a aproximação anual do seguro de cuidados.", example: { question: "Qual o resultado para salário bruto mensal de ¥300.000 e idade abaixo de 40?", answer: "O bruto anualizado é ¥3.600.000. O motor mostra médias mensais de imposto de renda ¥3.922, imposto residencial ¥12.772, seguro social ¥43.950, deduções totais ¥60.644 e líquido modelado ¥239.356. É a estimativa anual distribuída por 12 meses." }, faq: { question: "Inclui bônus ou variações de um mês para outro?", answer: "Não. Supõe o mesmo salário nos 12 meses; bônus, bases reais de contribuição mensal e diferenças regionais, de dependentes ou seguradora não são calculados. Usa o mesmo modelo anual e pode haver pequenas diferenças de arredondamento." } },
  },
  de: {
    annual: { description: "Schätzt das jährliche und durchschnittliche monatliche Nettogehalt in Japan, indem modellierte Steuern und Sozialbeiträge vom Jahresbrutto abgezogen werden. Keine individuelle Lohnabrechnung.", howTo: "Jahresbrutto eingeben und Altersgruppe unter 40 oder ab 40 wählen. Ab 40 kommt der modellierte Pflegeversicherungsanteil hinzu; verwendet werden die eingerichteten Annahmen des Szenarios 2026.", formula: "Arbeitseinkommen = Jahresbrutto − Gehaltsfreibetrag. Modellierte Sozialbeiträge und Grundfreibetrag werden abgezogen; die steuerpflichtige Basis wird auf volle ¥1.000 abgerundet. Die Einkommensteuer nutzt die konfigurierten Tarifstufen plus Wiederaufbauzuschlag. Die Einwohnersteuer ist eine vereinfachte Schätzung für das Folgejahr. Jahresnetto = Brutto − Sozialbeiträge − beide Steuern; Monatsmittel = Jahresnetto ÷ 12.", example: { question: "Was ergibt ¥3.600.000 Jahresbrutto für eine Person unter 40?", answer: "Das Modell liefert Arbeitseinkommen ¥2.440.000, Einkommensteuer ¥47.068, geschätzte Einwohnersteuer des Folgejahres ¥153.260, modellierte Sozialbeiträge ¥527.400, Jahresnetto ¥2.872.272 und Monatsmittel ¥239.356. Das sind Modellwerte, keine garantierte Abrechnung." }, faq: { question: "Warum kann das tatsächliche Nettogehalt in Japan abweichen?", answer: "Die Krankenversicherung nutzt einen 5%-Ersatzwert. Versicherer- und Regionaltarife, Beitragsobergrenzen, Boni, Angehörige und persönliche Abzüge sowie kommunale Unterschiede werden nicht vollständig modelliert. Die Anwendbarkeit der Abzüge für 2026 wird noch abgeglichen; das Ergebnis ist keine bestätigte aktuelle Rechtsberechnung." } },
    monthly: { description: "Rechnet japanischen Monatslohn auf ein Jahr hoch, wendet das Jahresmodell an und zeigt Abzüge sowie Netto als Monatsmittel. Keine Abrechnung für einen konkreten Monat.", howTo: "Monatliches Bruttogehalt eingeben und Altersgruppe wählen. Das Modell multipliziert mit 12, berechnet die Jahreswerte und teilt sie durch 12. Boni werden nicht separat eingegeben und bleiben unberücksichtigt.", formula: "Hochgerechnetes Jahresbrutto = Monatslohn × 12. Jährliche Gehaltsabzüge, Versicherungen und Steuern werden modelliert; jeder Jahreswert wird durch 12 geteilt und auf Yen gerundet. Ab 40 wird der Pflegeversicherungs-Ersatzwert einbezogen.", example: { question: "Was ergibt ¥300.000 Monatsbrutto für eine Person unter 40?", answer: "Das hochgerechnete Jahresbrutto beträgt ¥3.600.000. Das Modell zeigt monatlich im Mittel Einkommensteuer ¥3.922, Einwohnersteuer ¥12.772, Sozialbeiträge ¥43.950, Abzüge insgesamt ¥60.644 und modelliertes Netto ¥239.356. Es verteilt die Jahresschätzung auf zwölf Monate." }, faq: { question: "Sind Boni oder monatliche Schwankungen enthalten?", answer: "Nein. Der eingegebene Monatslohn gilt für alle zwölf Monate. Boni, tatsächliche monatliche Beitragsgrundlagen sowie regionale, familiäre und versichererspezifische Bedingungen werden nicht berechnet. Dasselbe Jahresmodell wird verwendet; Yen-Rundungen können kleine Abweichungen verursachen." } },
  },
  fr: {
    annual: { description: "Estime le net annuel et mensuel moyen au Japon en retranchant les impôts et cotisations modélisés du salaire brut annuel. Ce n’est pas une fiche de paie individuelle officielle.", howTo: "Saisissez le brut annuel et choisissez moins de 40 ans ou 40 ans et plus. Le second choix ajoute l’estimation du régime de soins ; le calcul suit les hypothèses configurées pour le scénario 2026.", formula: "Revenu salarial = salaire annuel − abattement salarial. On déduit les cotisations sociales modélisées et l’abattement de base applicable, puis la base imposable est arrondie vers le bas au millier de yens. L’impôt sur le revenu suit les tranches configurées et la surtaxe de reconstruction. L’impôt résidentiel est une estimation simplifiée de l’année suivante. Net annuel = brut − cotisations − les deux impôts ; moyenne mensuelle = net annuel ÷ 12.", example: { question: "Quel résultat pour ¥3 600 000 de brut annuel avant 40 ans ?", answer: "Le moteur renvoie un revenu salarial de ¥2 440 000, un impôt modélisé de ¥47 068, un impôt résidentiel estimé pour l’année suivante de ¥153 260, des cotisations modélisées de ¥527 400, un net annuel de ¥2 872 272 et une moyenne mensuelle de ¥239 356. Ce sont des résultats de modèle, pas une fiche garantie." }, faq: { question: "Pourquoi le net réel japonais peut-il différer ?", answer: "L’assurance santé repose sur une hypothèse de 5 % ; les différences d’assureur et de région, plafonds, bonus, personnes à charge et déductions personnelles, ainsi que les variations municipales ne sont pas entièrement modélisés. L’applicabilité des déductions 2026 reste à concilier ; n’utilisez pas ce résultat comme montant légal actuel." } },
    monthly: { description: "Annualise un salaire mensuel japonais, applique le modèle annuel puis affiche chaque retenue et le net en moyenne mensuelle. Ce n’est pas la fiche d’un mois donné.", howTo: "Saisissez le brut mensuel et choisissez la tranche d’âge. Le moteur multiplie par 12, applique le modèle annuel puis divise les résultats par 12. Les primes ne sont pas saisies et ne sont pas incluses.", formula: "Brut annualisé = salaire mensuel × 12. Le modèle applique les déductions salariales, assurances et impôts annuels ; chaque résultat est divisé par 12 et arrondi au yen. Le choix 40 ans et plus ajoute l’estimation annuelle de l’assurance soins.", example: { question: "Quel résultat pour ¥300 000 bruts par mois avant 40 ans ?", answer: "Le brut annualisé est ¥3 600 000. Le moteur affiche en moyenne mensuelle ¥3 922 d’impôt sur le revenu, ¥12 772 d’impôt résidentiel, ¥43 950 de cotisations, ¥60 644 de retenues totales et ¥239 356 de net modélisé. C’est l’estimation annuelle répartie sur douze mois." }, faq: { question: "Les primes ou les variations mensuelles sont-elles incluses ?", answer: "Non. Le salaire saisi est supposé identique pendant douze mois ; primes, assiettes réelles mensuelles et différences régionales, familiales ou d’assureur ne sont pas calculées. Le modèle annuel est réutilisé et l’arrondi au yen peut créer un léger écart." } },
  },
  vi: {
    annual: { description: "Ước tính thu nhập ròng năm và bình quân tháng tại Nhật bằng cách trừ thuế và bảo hiểm xã hội mô hình khỏi lương gộp năm. Không phải phiếu lương cá nhân chính thức.", howTo: "Nhập lương gộp năm và chọn dưới 40 tuổi hoặc từ 40 tuổi. Lựa chọn từ 40 tuổi cộng thêm khoản bảo hiểm chăm sóc theo mô hình; phép tính dùng giả định kịch bản 2026 đã cấu hình.", formula: "Thu nhập tiền lương = lương năm − khoản khấu trừ lương. Trừ bảo hiểm xã hội mô hình và khấu trừ cơ bản tương ứng, rồi làm tròn xuống cơ sở tính thuế theo 1.000 yên. Thuế thu nhập dùng các bậc lũy tiến đã cấu hình cộng thuế phụ tái thiết. Thuế cư trú là ước tính đơn giản cho năm sau. Thực nhận năm = lương gộp − bảo hiểm − hai khoản thuế; bình quân tháng = thực nhận năm ÷ 12.", example: { question: "Lương gộp năm ¥3.600.000, dưới 40 tuổi thì kết quả ra sao?", answer: "Máy tính trả thu nhập tiền lương ¥2.440.000, thuế thu nhập mô hình ¥47.068, thuế cư trú năm sau ước tính ¥153.260, bảo hiểm xã hội ¥527.400, thực nhận năm ¥2.872.272 và bình quân tháng ¥239.356. Đây là kết quả mô hình, không đảm bảo khớp phiếu lương." }, faq: { question: "Vì sao tiền thực nhận ở Nhật có thể khác?", answer: "Bảo hiểm y tế dùng giả định 5%; chưa mô hình đầy đủ mức phí theo nhà bảo hiểm/tỉnh, trần đóng, thưởng, người phụ thuộc và khấu trừ cá nhân, hay khác biệt địa phương. Thời điểm áp dụng bảng khấu trừ 2026 còn cần đối chiếu; không xem đây là số tiền pháp lý hiện hành." } },
    monthly: { description: "Quy đổi lương tháng tại Nhật thành năm, áp dụng mô hình năm rồi hiển thị các khoản khấu trừ và thực nhận bình quân tháng. Không phải phiếu lương của một tháng cụ thể.", howTo: "Nhập lương gộp tháng và chọn nhóm tuổi. Máy tính nhân 12, chạy mô hình lương năm rồi chia kết quả cho 12. Không có trường nhập thưởng nên thưởng không được tính.", formula: "Lương gộp quy năm = lương tháng × 12. Áp dụng mô hình khấu trừ lương, bảo hiểm và thuế năm; mỗi kết quả chia 12 và làm tròn đến yên. Từ 40 tuổi, mô hình cộng khoản bảo hiểm chăm sóc giả định vào năm.", example: { question: "Lương gộp tháng ¥300.000, dưới 40 tuổi thì kết quả ra sao?", answer: "Lương quy năm là ¥3.600.000. Máy tính hiển thị bình quân tháng: thuế thu nhập ¥3.922, thuế cư trú ¥12.772, bảo hiểm xã hội ¥43.950, tổng khấu trừ ¥60.644 và thực nhận mô hình ¥239.356. Đây là ước tính năm chia đều cho 12 tháng." }, faq: { question: "Có tính thưởng hoặc thay đổi từng tháng không?", answer: "Không. Công cụ giả định mức lương đã nhập được trả trong cả 12 tháng; không tính thưởng, căn cứ đóng thực tế từng tháng hay khác biệt tỉnh, người phụ thuộc và nhà bảo hiểm. Dùng chung mô hình năm nên có thể chênh nhẹ do làm tròn yên." } },
  },
  id: {
    annual: { description: "Memperkirakan take-home tahunan dan rata-rata bulanan di Jepang dengan mengurangi pajak dan asuransi sosial model dari gaji bruto tahunan. Bukan slip gaji resmi individual.", howTo: "Masukkan gaji bruto tahunan dan pilih usia di bawah 40 atau 40 tahun ke atas. Pilihan 40+ menambahkan proksi asuransi perawatan; asumsi skenario 2026 yang dikonfigurasi digunakan.", formula: "Penghasilan kerja = gaji tahunan − pengurang penghasilan gaji. Kurangi asuransi sosial model dan pengurang dasar sesuai kelompok, lalu bulatkan turun basis pajak ke ¥1.000. Pajak penghasilan memakai lapisan progresif konfigurasi plus surtaks rekonstruksi. Pajak penduduk adalah taksiran sederhana tahun berikutnya. Bersih tahunan = bruto − asuransi sosial − kedua pajak; rata-rata bulanan = bersih tahunan ÷ 12.", example: { question: "Apa hasil untuk bruto tahunan ¥3.600.000 dan usia di bawah 40?", answer: "Mesin menghasilkan penghasilan kerja ¥2.440.000, pajak penghasilan model ¥47.068, pajak penduduk tahun depan ¥153.260, asuransi sosial model ¥527.400, take-home tahunan ¥2.872.272 dan rata-rata bulanan ¥239.356. Ini keluaran model, bukan slip gaji yang dijamin." }, faq: { question: "Mengapa take-home aktual di Jepang bisa berbeda?", answer: "Asuransi kesehatan memakai proksi 5%; variasi perusahaan asuransi/prefektur, batas iuran, bonus, tanggungan dan pengurang pribadi, serta perbedaan pemerintah kota tidak dimodelkan penuh. Tanggal penerapan jadwal pengurang 2026 masih perlu dicocokkan; jangan anggap ini jumlah resmi yang berlaku." } },
    monthly: { description: "Mengannualisasi gaji bulanan Jepang, menjalankan model tahunan, lalu menampilkan potongan dan take-home sebagai rata-rata bulanan. Bukan slip untuk bulan tertentu.", howTo: "Masukkan gaji bruto bulanan dan pilih kelompok usia. Mesin mengalikan dengan 12, menerapkan model tahunan, lalu membagi hasilnya dengan 12. Bonus tidak punya input dan tidak disertakan.", formula: "Bruto tahunan = gaji bulanan × 12. Model pengurang gaji, asuransi, dan pajak tahunan diterapkan; setiap hasil dibagi 12 dan dibulatkan ke yen. Opsi usia 40+ menambah proksi asuransi perawatan tahunan.", example: { question: "Apa hasil untuk bruto bulanan ¥300.000 dan usia di bawah 40?", answer: "Bruto tahunan menjadi ¥3.600.000. Mesin menampilkan rata-rata bulanan: pajak penghasilan ¥3.922, pajak penduduk ¥12.772, asuransi sosial ¥43.950, total potongan ¥60.644, dan take-home model ¥239.356. Ini taksiran tahunan yang dibagi ke 12 bulan." }, faq: { question: "Apakah bonus atau perubahan tiap bulan dihitung?", answer: "Tidak. Gaji yang dimasukkan dianggap sama selama 12 bulan; bonus, basis iuran bulanan aktual, dan variasi daerah, tanggungan, atau perusahaan asuransi tidak dihitung. Model tahunan yang sama dipakai dan pembulatan yen dapat menyebabkan selisih kecil." } },
  },
  th: {
    annual: { description: "ประมาณเงินสุทธิรายปีและค่าเฉลี่ยรายเดือนในญี่ปุ่น โดยหักภาษีและประกันสังคมตามแบบจำลองจากเงินเดือนรวม ไม่ใช่การคำนวณสลิปเงินเดือนรายบุคคลอย่างเป็นทางการ", howTo: "กรอกเงินเดือนรวมรายปีและเลือกอายุต่ำกว่า 40 ปีหรือ 40 ปีขึ้นไป ตัวเลือก 40 ปีขึ้นไปจะเพิ่มค่าประกันการดูแลตามแบบจำลอง และใช้สมมติฐานสถานการณ์ปี 2026 ที่ตั้งไว้", formula: "รายได้จากเงินเดือน=เงินเดือนรายปี−ค่าหักเงินเดือน หักประกันสังคมแบบจำลองและค่าลดหย่อนพื้นฐานตามช่วงรายได้ จากนั้นปัดฐานภาษีลงทีละ 1,000 เยน ภาษีเงินได้ใช้ขั้นอัตราก้าวหน้าที่ตั้งไว้บวกภาษีฟื้นฟู ภาษีผู้อยู่อาศัยเป็นค่าประมาณแบบง่ายของปีถัดไป เงินสุทธิรายปี=เงินเดือนรวม−ประกันสังคม−ภาษีทั้งสอง; เฉลี่ยรายเดือน=รายปี÷12", example: { question: "เงินเดือนรวมรายปี ¥3,600,000 และอายุต่ำกว่า 40 ปีได้เท่าไร?", answer: "เครื่องคำนวณให้รายได้จากเงินเดือน ¥2,440,000 ภาษีเงินได้จำลอง ¥47,068 ภาษีผู้อยู่อาศัยปีถัดไป ¥153,260 ประกันสังคม ¥527,400 เงินสุทธิรายปี ¥2,872,272 และเฉลี่ยเดือนละ ¥239,356 เป็นผลจากแบบจำลอง ไม่รับประกันว่าจะตรงกับสลิปจริง" }, faq: { question: "เหตุใดเงินสุทธิจริงในญี่ปุ่นจึงต่างออกไปได้?", answer: "ประกันสุขภาพใช้สมมติฐานแทน 5%; ยังไม่จำลองความต่างตามผู้ประกัน/จังหวัด เพดานเงินสมทบ โบนัส ผู้พึ่งพิงและค่าลดหย่อนส่วนบุคคล หรือเทศบาลครบถ้วน วันที่เริ่มใช้ตารางลดหย่อนปี 2026 ยังต้องตรวจสอบ อย่าใช้เป็นยอดตามกฎหมายปัจจุบัน" } },
    monthly: { description: "คูณเงินเดือนรายเดือนในญี่ปุ่นเป็นรายปี ใช้แบบจำลองรายปี แล้วแสดงรายการหักและเงินสุทธิเป็นค่าเฉลี่ยรายเดือน ไม่ใช่สลิปของเดือนใดเดือนหนึ่ง", howTo: "กรอกเงินเดือนรวมรายเดือนและเลือกช่วงอายุ เครื่องจะคูณ 12 ใช้แบบจำลองรายปี แล้วหารผลลัพธ์ด้วย 12 ไม่มีช่องกรอกโบนัส จึงไม่รวมโบนัส", formula: "เงินเดือนรวมต่อปี=เงินเดือนรายเดือน×12 ใช้แบบจำลองค่าหัก ประกัน และภาษีรายปี จากนั้นหารแต่ละผลด้วย 12 และปัดเป็นเยน ตัวเลือกอายุ 40 ปีขึ้นไปเพิ่มค่าประกันการดูแลตามแบบจำลอง", example: { question: "เงินเดือนรวมเดือนละ ¥300,000 และอายุต่ำกว่า 40 ปีได้เท่าไร?", answer: "ยอดต่อปีคือ ¥3,600,000 ค่าเฉลี่ยรายเดือนที่แสดงคือภาษีเงินได้ ¥3,922 ภาษีผู้อยู่อาศัย ¥12,772 ประกันสังคม ¥43,950 หักรวม ¥60,644 และเงินสุทธิจำลอง ¥239,356 เป็นการนำค่าประมาณรายปีมาเฉลี่ย 12 เดือน" }, faq: { question: "รวมโบนัสหรือความเปลี่ยนแปลงรายเดือนไหม?", answer: "ไม่รวม โดยถือว่าเงินเดือนที่กรอกได้รับครบ 12 เดือน ไม่คำนวณโบนัส ฐานเงินสมทบจริงรายเดือน หรือความต่างด้านพื้นที่ ผู้พึ่งพิง และผู้ประกัน ใช้แบบจำลองรายปีเดียวกันและอาจต่างเล็กน้อยจากการปัดเยน" } },
  },
  "zh-tw": {
    annual: { description: "從日本年薪扣除模型估算的稅金與社會保險，顯示年度及月平均實領額；不是個人法定薪資單核算。", howTo: "輸入年度稅前薪資，選擇未滿40歲或40歲以上。40歲以上會加上模型照護保險估值，並使用設定的2026情境假設。", formula: "薪資所得=年薪−薪資所得扣除。再扣除模型社會保險與對應所得級距的基本扣除，課稅所得向下取整至1,000日圓。所得稅採設定的累進級距並加重建特別稅；居民稅是次年度簡化估算。年實領=年薪−社保−兩項稅；月平均=年實領÷12。", example: { question: "未滿40歲、年薪3,600,000日圓時結果為何？", answer: "引擎回傳薪資所得2,440,000日圓、模型所得稅47,068日圓、次年度居民稅估算153,260日圓、模型社保527,400日圓、年實領2,872,272日圓及月平均239,356日圓。這是模型結果，不保證等於實際薪資單。" }, faq: { question: "為什麼日本實際實領金額可能不同？", answer: "健康保險以5%代用假設計算，未完整納入保險機構與地區差異、提繳上限、獎金、扶養及個人扣除、地方居民稅差異。2026扣除表的適用時點仍待核對，請勿視為現行法定金額。" } },
    monthly: { description: "將日本月薪乘以12套用年度模型，再把各項扣款和實領額換算成月平均；不是特定月份的薪資單。", howTo: "輸入月稅前薪資並選擇年齡級距。引擎先乘12進行年薪估算，再將年度結果除以12；沒有獎金輸入欄，因此不計獎金。", formula: "年換算總薪資=月薪×12。套用年度薪資扣除、保險與稅額模型後，各年額除以12並四捨五入至日圓。選擇40歲以上會加上模型照護保險估值。", example: { question: "未滿40歲、月薪300,000日圓時結果為何？", answer: "年換算總額為3,600,000日圓。引擎顯示月均所得稅3,922日圓、居民稅12,772日圓、社保43,950日圓、扣款合計60,644日圓、模型實領239,356日圓。這是年度估算平均分配至12個月。" }, faq: { question: "會計入獎金或每月變動嗎？", answer: "不會。假設輸入的月薪支付12個月；不計獎金、實際逐月提繳基礎，以及地區、扶養或保險機構差異。與年薪工具共用年度模型，日圓取整可能造成些微差異。" } },
  },
  it: {
    annual: { description: "Stima il netto annuo e la media mensile in Giappone sottraendo imposte e contributi sociali modellati dal lordo annuo. Non è una busta paga individuale ufficiale.", howTo: "Inserisci il lordo annuo e scegli meno di 40 anni oppure 40 anni o più. La seconda scelta aggiunge la stima del contributo per assistenza; vengono usate le ipotesi configurate per lo scenario 2026.", formula: "Reddito da lavoro = lordo annuo − deduzione salariale. Si sottraggono i contributi sociali modellati e la deduzione di base della fascia; l’imponibile viene arrotondato per difetto a ¥1.000. L’imposta sul reddito usa gli scaglioni configurati più l’addizionale per la ricostruzione. L’imposta residente è una stima semplificata dell’anno successivo. Netto annuo = lordo − contributi − entrambe le imposte; media mensile = netto ÷ 12.", example: { question: "Quanto risulta con ¥3.600.000 lordi annui e meno di 40 anni?", answer: "Il motore restituisce reddito da lavoro ¥2.440.000, imposta modellata ¥47.068, imposta residente stimata per l’anno successivo ¥153.260, contributi modellati ¥527.400, netto annuo ¥2.872.272 e media mensile ¥239.356. È un risultato del modello, non una busta paga garantita." }, faq: { question: "Perché il netto effettivo in Giappone può differire?", answer: "L’assicurazione sanitaria usa un’ipotesi del 5%; tariffe per ente e prefettura, massimali, bonus, familiari a carico e detrazioni personali e differenze comunali non sono modellati integralmente. La decorrenza delle deduzioni 2026 è ancora da riconciliare: non considerare il risultato un importo legale attuale." } },
    monthly: { description: "Annualizza lo stipendio mensile giapponese, applica il modello annuo e mostra deduzioni e netto come media mensile. Non è il cedolino di un mese specifico.", howTo: "Inserisci il lordo mensile e scegli la fascia d’età. Il motore moltiplica per 12, applica il modello annuale e divide i risultati per 12. I bonus non hanno un campo dedicato e non vengono inclusi.", formula: "Lordo annualizzato = stipendio mensile × 12. Si applica il modello annuale di deduzioni, assicurazioni e imposte; ogni risultato viene diviso per 12 e arrotondato allo yen. La scelta 40+ aggiunge la stima annua dell’assicurazione assistenziale.", example: { question: "Quanto risulta con ¥300.000 lordi al mese e meno di 40 anni?", answer: "Il lordo annualizzato è ¥3.600.000. Il motore mostra medie mensili: imposta sul reddito ¥3.922, imposta residente ¥12.772, contributi ¥43.950, deduzioni totali ¥60.644 e netto modellato ¥239.356. È la stima annuale ripartita su 12 mesi." }, faq: { question: "Sono inclusi bonus o variazioni mensili?", answer: "No. Si presume lo stesso stipendio per 12 mesi; bonus, basi contributive mensili effettive e differenze regionali, familiari o dell’assicuratore non sono calcolati. Si usa il modello annuale e gli arrotondamenti allo yen possono produrre lievi differenze." } },
  },
  nl: {
    annual: { description: "Schat het jaarlijkse en gemiddelde maandelijkse nettoloon in Japan door gemodelleerde belastingen en sociale premies van het jaarbruto af te trekken. Geen officiële persoonlijke loonstrookberekening.", howTo: "Vul het jaarlijkse brutoloon in en kies jonger dan 40 of 40 jaar en ouder. De keuze 40+ voegt de modelinschatting voor langdurige zorg toe; de ingestelde aannames voor scenario 2026 worden gebruikt.", formula: "Arbeidsinkomen = jaarloon − looninkomensaftrek. Trek de gemodelleerde sociale premies en toepasselijke basisaftrek af en rond de belastbare basis naar beneden af op ¥1.000. Inkomstenbelasting volgt de ingestelde schijven plus reconstructietoeslag. Inwonersbelasting is een vereenvoudigde schatting voor volgend jaar. Jaar-netto = bruto − sociale premies − beide belastingen; maandgemiddelde = jaar-netto ÷ 12.", example: { question: "Wat geeft ¥3.600.000 jaarbruto voor iemand jonger dan 40?", answer: "De engine geeft arbeidsinkomen ¥2.440.000, modelbelasting ¥47.068, geschatte inwonersbelasting volgend jaar ¥153.260, sociale premies ¥527.400, jaar-netto ¥2.872.272 en maandgemiddelde ¥239.356. Dit zijn modeluitkomsten, geen gegarandeerde loonstrook." }, faq: { question: "Waarom kan het echte nettoloon in Japan afwijken?", answer: "Zorgverzekering gebruikt een proxy van 5%; verschillen per verzekeraar/prefectuur, premieplafonds, bonussen, gezinsleden en persoonlijke aftrek en gemeentelijke verschillen zijn niet volledig gemodelleerd. De toepassingsdatum van de aftrekregels voor 2026 wordt nog afgestemd; gebruik dit niet als bevestigd huidig wettelijk bedrag." } },
    monthly: { description: "Rekent Japans maandloon om naar een jaar, past het jaarmodel toe en toont aftrek en netto als maandgemiddelden. Geen loonstrook van één specifieke maand.", howTo: "Vul het maandelijkse brutoloon in en kies de leeftijdsgroep. De engine vermenigvuldigt met 12, past het jaarmodel toe en deelt de uitkomsten door 12. Bonussen worden niet ingevoerd en blijven buiten beschouwing.", formula: "Jaarbruto = maandloon × 12. Het model past jaarlijkse loon-, verzekerings- en belastingregels toe; elk jaarbedrag wordt door 12 gedeeld en op yen afgerond. De optie 40+ voegt de jaarlijkse proxy voor langdurige zorg toe.", example: { question: "Wat geeft ¥300.000 bruto per maand voor iemand jonger dan 40?", answer: "Het omgerekende jaarbruto is ¥3.600.000. De engine toont maandgemiddelden van inkomstenbelasting ¥3.922, inwonersbelasting ¥12.772, sociale premies ¥43.950, totale aftrek ¥60.644 en model-netto ¥239.356. Het jaarmodel wordt over twaalf maanden verdeeld." }, faq: { question: "Zijn bonussen of maandelijkse wijzigingen inbegrepen?", answer: "Nee. Het ingevoerde loon wordt verondersteld alle twaalf maanden gelijk te zijn; bonussen, echte maandelijkse premiegrondslagen en verschillen per regio, huishouden of verzekeraar worden niet berekend. Hetzelfde jaarmodel wordt gebruikt; yenafronding kan kleine verschillen geven." } },
  },
  hi: {
    annual: { description: "जापान में वार्षिक सकल वेतन से मॉडल किए गए कर और सामाजिक बीमा घटाकर वार्षिक तथा औसत मासिक शुद्ध वेतन का अनुमान देता है। यह व्यक्तिगत आधिकारिक वेतन-पर्ची नहीं है।", howTo: "वार्षिक सकल वेतन भरें और 40 से कम या 40+ आयु चुनें। 40+ विकल्प मॉडल देखभाल बीमा अनुमान जोड़ता है; गणना में कॉन्फ़िगर किए गए 2026 परिदृश्य के अनुमान लागू हैं।", formula: "रोजगार आय = वार्षिक वेतन − वेतन आय कटौती। मॉडल सामाजिक बीमा और लागू मूल कटौती घटाकर कर योग्य आधार को ¥1,000 तक नीचे पूर्णांकित करता है। आयकर कॉन्फ़िगर की गई प्रगतिशील दरों और पुनर्निर्माण अधिभार से निकाला जाता है। निवासी कर अगले वर्ष का सरल अनुमान है। वार्षिक शुद्ध = सकल − सामाजिक बीमा − दोनों कर; मासिक औसत = वार्षिक शुद्ध ÷ 12।", example: { question: "40 से कम आयु में ¥3,600,000 वार्षिक सकल पर क्या परिणाम है?", answer: "इंजन रोजगार आय ¥2,440,000, मॉडल आयकर ¥47,068, अगले वर्ष का निवासी कर अनुमान ¥153,260, सामाजिक बीमा ¥527,400, वार्षिक शुद्ध ¥2,872,272 और मासिक औसत ¥239,356 देता है। ये मॉडल परिणाम हैं, सुनिश्चित वेतन-पर्ची नहीं।" }, faq: { question: "जापान का वास्तविक शुद्ध वेतन अलग क्यों हो सकता है?", answer: "स्वास्थ्य बीमा 5% के प्रॉक्सी पर आधारित है; बीमाकर्ता/प्रान्त की दरें, योगदान सीमा, बोनस, आश्रित और व्यक्तिगत कटौतियाँ तथा नगरपालिकाओं का अंतर पूरी तरह शामिल नहीं हैं। 2026 कटौती-सारणी की लागू तारीख का मिलान बाकी है; इसे वर्तमान कानूनी राशि न मानें।" } },
    monthly: { description: "जापानी मासिक वेतन को वार्षिक बनाकर वार्षिक मॉडल चलाता है और कटौतियों व शुद्ध वेतन को मासिक औसत के रूप में दिखाता है। यह किसी खास महीने की पर्ची नहीं है।", howTo: "मासिक सकल वेतन भरें और आयु वर्ग चुनें। इंजन वेतन को 12 से गुणा करके वार्षिक मॉडल लगाता है और परिणामों को 12 से भाग देता है। बोनस के लिए इनपुट नहीं है, इसलिए बोनस शामिल नहीं होता।", formula: "वार्षिक समतुल्य सकल = मासिक वेतन × 12। वार्षिक वेतन कटौती, बीमा और कर मॉडल लागू होते हैं; प्रत्येक वार्षिक परिणाम को 12 से भाग देकर येन तक गोल किया जाता है। 40+ विकल्प मॉडल देखभाल बीमा जोड़ता है।", example: { question: "40 से कम आयु में ¥300,000 मासिक सकल पर क्या परिणाम है?", answer: "वार्षिक समतुल्य ¥3,600,000 है। इंजन मासिक औसत आयकर ¥3,922, निवासी कर ¥12,772, सामाजिक बीमा ¥43,950, कुल कटौती ¥60,644 और मॉडल शुद्ध ¥239,356 दिखाता है। यह वार्षिक अनुमान को 12 महीनों में बाँटता है।" }, faq: { question: "क्या बोनस या हर महीने के बदलाव शामिल हैं?", answer: "नहीं। दर्ज वेतन को सभी 12 महीनों के लिए समान माना जाता है; बोनस, वास्तविक मासिक योगदान आधार तथा क्षेत्र, आश्रित या बीमाकर्ता के अंतर की गणना नहीं होती। वार्षिक मॉडल साझा है और येन पूर्णांकन से थोड़ा अंतर हो सकता है।" } },
  },
  ru: {
    annual: { description: "Оценивает годовую и среднемесячную зарплату нетто в Японии, вычитая модельные налоги и социальные взносы из годового брутто. Это не индивидуальный официальный расчётный листок.", howTo: "Введите годовую зарплату брутто и выберите возраст до 40 лет или от 40 лет. Во втором случае добавляется модельная оценка страхования ухода; используются заданные предположения сценария 2026 года.", formula: "Трудовой доход = годовая зарплата − вычет по зарплате. Вычитаются модельные соцвзносы и базовый вычет для соответствующего диапазона; налогооблагаемая база округляется вниз до ¥1 000. Подоходный налог рассчитывается по заданной прогрессивной шкале и надбавке на восстановление. Жилищный налог — упрощённая оценка на следующий год. Нетто за год = брутто − соцвзносы − оба налога; среднемесячно = годовое нетто ÷ 12.", example: { question: "Что получится при годовом брутто ¥3 600 000 и возрасте до 40 лет?", answer: "Модель возвращает трудовой доход ¥2 440 000, подоходный налог ¥47 068, оценку жилищного налога следующего года ¥153 260, соцвзносы ¥527 400, годовое нетто ¥2 872 272 и среднемесячно ¥239 356. Это результат модели, а не гарантированный расчётный листок." }, faq: { question: "Почему фактическая зарплата нетто в Японии может отличаться?", answer: "Для медицинского страхования используется условная ставка 5%; тарифы страховщика и региона, пределы взносов, бонусы, иждивенцы и личные вычеты, а также муниципальные различия учтены не полностью. Дату применения вычетов 2026 года ещё нужно согласовать; не считайте результат подтверждённой текущей суммой по закону." } },
    monthly: { description: "Пересчитывает месячную зарплату в годовую, применяет годовую модель и показывает вычеты и нетто как среднемесячные значения. Это не ведомость за конкретный месяц.", howTo: "Введите месячную зарплату брутто и возрастную группу. Модель умножает сумму на 12, применяет годовой расчёт и делит результаты на 12. Бонусы отдельно не вводятся и не учитываются.", formula: "Годовое брутто = месячная зарплата × 12. Применяются годовые модели вычетов, страхования и налогов; каждый результат делится на 12 и округляется до иены. Вариант 40+ включает модельную оценку страхования ухода за год.", example: { question: "Что получится при месячном брутто ¥300 000 и возрасте до 40 лет?", answer: "Годовая сумма — ¥3 600 000. Модель показывает среднемесячно: подоходный налог ¥3 922, жилищный налог ¥12 772, соцвзносы ¥43 950, всего удержаний ¥60 644 и модельное нетто ¥239 356. Годовая оценка распределена на 12 месяцев." }, faq: { question: "Учитываются бонусы и изменения по месяцам?", answer: "Нет. Введённая зарплата предполагается одинаковой все 12 месяцев; бонусы, фактическая ежемесячная база взносов и региональные, семейные или страховые условия не рассчитываются. Используется та же годовая модель, округление до иены может дать небольшую разницу." } },
  },
  tr: {
    annual: { description: "Japonya'daki yıllık brüt maaştan modellenen vergi ve sosyal sigortayı düşerek yıllık ve aylık ortalama net maaşı tahmin eder. Kişiye özel resmî bordro hesabı değildir.", howTo: "Yıllık brüt maaşı girin ve 40 yaş altı veya 40+ seçin. 40+ seçeneği model bakım sigortası tahminini ekler; yapılandırılmış 2026 senaryo varsayımları kullanılır.", formula: "Çalışma geliri = yıllık maaş − maaş geliri indirimi. Modellenen sosyal sigorta ve ilgili temel indirim düşülür; vergi matrahı ¥1.000'e aşağı yuvarlanır. Gelir vergisinde yapılandırılmış artan oranlar ve yeniden inşa ek vergisi kullanılır. İkamet vergisi sonraki yıl için basit tahmindir. Yıllık net = brüt − sosyal sigorta − iki vergi; aylık ortalama = yıllık net ÷ 12.", example: { question: "40 yaş altı için yıllık ¥3.600.000 brüt ne verir?", answer: "Motor çalışma gelirini ¥2.440.000, modellenen gelir vergisini ¥47.068, gelecek yıl ikamet vergisi tahminini ¥153.260, sosyal sigortayı ¥527.400, yıllık neti ¥2.872.272 ve aylık ortalamayı ¥239.356 verir. Bunlar model çıktısıdır, garantili bordro değildir." }, faq: { question: "Japonya'daki gerçek net maaş neden farklı olabilir?", answer: "Sağlık sigortası %5 vekil oran kullanır; sigortacı/il oranları, katkı üst sınırları, ikramiyeler, bakmakla yükümlü olunan kişiler ve kişisel indirimler ile belediye farkları tam modellenmez. 2026 indirim çizelgesinin uygulanma tarihi hâlâ uzlaştırılmalıdır; sonucu yürürlükteki kesin yasal tutar saymayın." } },
    monthly: { description: "Japon aylık maaşını yıllığa çevirir, yıllık modeli uygular ve kesinti ile net tutarı aylık ortalama olarak gösterir. Belirli bir aya ait bordro değildir.", howTo: "Aylık brüt maaşı girin ve yaş grubunu seçin. Motor maaşı 12 ile çarpar, yıllık modeli uygular ve sonuçları 12'ye böler. İkramiye girişi yoktur ve hesaba katılmaz.", formula: "Yıllık brüt = aylık maaş × 12. Yıllık indirim, sigorta ve vergi modeli uygulanır; her yıllık sonuç 12'ye bölünüp yen'e yuvarlanır. 40+ seçeneği yıllık model bakım sigortası tahminini ekler.", example: { question: "40 yaş altı için aylık ¥300.000 brüt ne verir?", answer: "Yıllığa çevrilen brüt ¥3.600.000'dır. Motor aylık ortalama gelir vergisi ¥3.922, ikamet vergisi ¥12.772, sosyal sigorta ¥43.950, toplam kesinti ¥60.644 ve model neti ¥239.356 gösterir. Yıllık tahmin 12 aya bölünmüştür." }, faq: { question: "İkramiye veya aydan aya değişiklikler dahil mi?", answer: "Hayır. Girilen maaşın 12 ay aynı olduğu varsayılır; ikramiye, gerçek aylık prim tabanı ve bölge, bakmakla yükümlü olunan kişi ya da sigortacı farkları hesaplanmaz. Yıllık model kullanılır; yen yuvarlaması küçük fark yaratabilir." } },
  },
  pl: {
    annual: { description: "Szacuje roczne i średnie miesięczne wynagrodzenie netto w Japonii, odejmując modelowane podatki i ubezpieczenia od rocznego brutto. To nie jest oficjalne indywidualne rozliczenie płac.", howTo: "Podaj roczne wynagrodzenie brutto i wybierz wiek poniżej 40 lat lub co najmniej 40 lat. Druga opcja dodaje modelową składkę opiekuńczą; używane są skonfigurowane założenia scenariusza 2026.", formula: "Dochód z pracy = roczne brutto − odliczenie od wynagrodzenia. Odejmowane są modelowane składki społeczne i właściwa ulga podstawowa; podstawa opodatkowania jest zaokrąglana w dół do ¥1 000. Podatek dochodowy korzysta ze skonfigurowanych progów progresywnych i dopłaty odbudowującej. Podatek rezydencki to uproszczona prognoza na kolejny rok. Netto roczne = brutto − składki − oba podatki; średnia miesięczna = netto ÷ 12.", example: { question: "Jaki wynik daje roczne brutto ¥3 600 000 dla osoby przed 40. rokiem życia?", answer: "Silnik zwraca dochód z pracy ¥2 440 000, modelowy podatek dochodowy ¥47 068, szacowany podatek rezydencki na kolejny rok ¥153 260, składki ¥527 400, netto roczne ¥2 872 272 i średnią miesięczną ¥239 356. To wynik modelu, nie gwarantowana lista płac." }, faq: { question: "Dlaczego rzeczywiste netto w Japonii może się różnić?", answer: "Ubezpieczenie zdrowotne korzysta z założenia 5%; stawki ubezpieczyciela i prefektury, limity składek, premie, osoby na utrzymaniu i ulgi osobiste oraz różnice gminne nie są w pełni modelowane. Termin stosowania tabeli ulg na 2026 r. wymaga jeszcze uzgodnienia; nie traktuj wyniku jako aktualnej kwoty ustawowej." } },
    monthly: { description: "Przelicza japońską pensję miesięczną na roczną, stosuje model roczny i pokazuje potrącenia oraz netto jako średnie miesięczne. To nie jest pasek płac z konkretnego miesiąca.", howTo: "Podaj miesięczne brutto i wybierz grupę wieku. Silnik mnoży pensję przez 12, stosuje model roczny i dzieli wyniki przez 12. Premii nie można wprowadzić, więc nie są uwzględniane.", formula: "Roczne brutto = pensja miesięczna × 12. Stosuje się roczny model ulg, ubezpieczeń i podatków; każdy wynik roczny jest dzielony przez 12 i zaokrąglany do jena. Wariant 40+ dodaje roczną modelową składkę opiekuńczą.", example: { question: "Jaki wynik daje miesięczne brutto ¥300 000 przed 40. rokiem życia?", answer: "Roczne brutto po przeliczeniu to ¥3 600 000. Silnik pokazuje miesięczne średnie: podatek dochodowy ¥3 922, rezydencki ¥12 772, składki ¥43 950, potrącenia łącznie ¥60 644 i modelowe netto ¥239 356. To roczna prognoza podzielona na 12 miesięcy." }, faq: { question: "Czy uwzględnia premie lub miesięczne zmiany?", answer: "Nie. Zakłada jednakową pensję przez 12 miesięcy; premie, rzeczywiste miesięczne podstawy składek i różnice regionalne, rodzinne lub ubezpieczyciela nie są liczone. Używany jest ten sam model roczny, a zaokrąglenia do jena mogą dać niewielką różnicę." } },
  },
  fil: {
    annual: { description: "Tinatantiya ang taunang at karaniwang buwanang net pay sa Japan sa pagbawas ng modelong buwis at social insurance mula sa taunang gross. Hindi ito opisyal na indibidwal na payslip.", howTo: "Ilagay ang taunang gross salary at piliin ang wala pang 40 o edad 40 pataas. Idinadagdag ng 40+ ang modelong care-insurance proxy; ginagamit ang naka-configure na palagay para sa 2026 scenario.", formula: "Employment income = taunang sahod − salary-income deduction. Ibawas ang modelong social insurance at naaangkop na basic deduction; ibaba sa susunod na ¥1,000 ang taxable base. Gumagamit ang income tax ng naka-configure na progressive bands at reconstruction surtax. Simpleng tantiya para sa susunod na taon ang resident tax. Taunang net = gross − insurance − dalawang buwis; buwanang average = taunang net ÷ 12.", example: { question: "Ano ang resulta sa ¥3,600,000 taunang gross at edad na wala pang 40?", answer: "Ibinabalik ng engine ang employment income na ¥2,440,000, modelong income tax na ¥47,068, tantiya sa resident tax sa susunod na taon na ¥153,260, social insurance na ¥527,400, taunang net na ¥2,872,272 at buwanang average na ¥239,356. Output ito ng modelo, hindi garantisadong payslip." }, faq: { question: "Bakit maaaring iba ang aktuwal na net pay sa Japan?", answer: "5% proxy ang gamit sa health insurance; hindi ganap na kasama ang pagkakaiba ng insurer/prefecture, contribution ceiling, bonus, dependents at personal deductions, at lokal na buwis. Kailangan pang itugma ang petsa ng bisa ng deduction schedule para sa 2026; huwag ituring itong kasalukuyang legal na halaga." } },
    monthly: { description: "Ginagawang taunang halaga ang buwanang sahod sa Japan, inilalapat ang taunang modelo, at ipinapakita ang mga kaltas at net bilang buwanang average. Hindi ito payslip ng isang partikular na buwan.", howTo: "Ilagay ang buwanang gross salary at piliin ang age group. Minumultiply ito ng 12, ginagamit ang taunang modelo, at hinahati sa 12 ang mga resulta. Walang bonus input kaya hindi kasama ang bonus.", formula: "Annualized gross = buwanang sahod × 12. Inilalapat ang taunang modelo ng salary deductions, insurance at buwis; hinahati sa 12 at niroround sa yen ang bawat taunang resulta. Idinadagdag ng 40+ ang taunang care-insurance proxy.", example: { question: "Ano ang resulta sa ¥300,000 buwanang gross at edad na wala pang 40?", answer: "¥3,600,000 ang annualized gross. Ipinapakita ng engine ang buwanang average: income tax ¥3,922, resident tax ¥12,772, social insurance ¥43,950, kabuuang kaltas ¥60,644 at modelong net ¥239,356. Hati ito ng taunang tantiya sa 12 buwan." }, faq: { question: "Kasama ba ang bonus o pagbabago kada buwan?", answer: "Hindi. Ipinapalagay na pareho ang sahod sa loob ng 12 buwan; hindi kinukuwenta ang bonus, aktuwal na buwanang contribution base, o pagkakaiba ayon sa rehiyon, dependent o insurer. Pareho ang taunang modelo at maaaring magkaroon ng maliit na diperensya dahil sa yen rounding." } },
  },
  bn: {
    annual: { description: "জাপানে বার্ষিক মোট বেতন থেকে মডেল করা কর ও সামাজিক বিমা বাদ দিয়ে বার্ষিক এবং মাসিক গড় হাতে-পাওয়ার অনুমান করে। এটি ব্যক্তিগত সরকারি বেতনপত্র নয়।", howTo: "বার্ষিক মোট বেতন লিখুন এবং ৪০ বছরের কম বা ৪০+ বাছুন। ৪০+ হলে মডেল পরিচর্যা-বিমার অনুমান যোগ হয়; কনফিগার করা ২০২৬ দৃশ্যকল্পের অনুমান ব্যবহৃত হয়।", formula: "কর্ম-আয় = বার্ষিক বেতন − বেতন-আয় ছাড়। মডেল সামাজিক বিমা ও প্রযোজ্য মূল ছাড় বাদ দিয়ে করযোগ্য ভিত্তি ¥1,000-এ নিচের দিকে পূর্ণসংখ্যা করা হয়। আয়কর কনফিগার করা প্রগতিশীল ধাপ ও পুনর্গঠন সারচার্জ ধরে; বাসিন্দা কর পরের বছরের সরল অনুমান। বার্ষিক নিট = মোট − বিমা − দুই কর; মাসিক গড় = বার্ষিক নিট ÷ 12।", example: { question: "৪০ বছরের কম বয়সে বার্ষিক মোট ¥3,600,000 হলে কী ফল?", answer: "ইঞ্জিন কর্ম-আয় ¥2,440,000, মডেল আয়কর ¥47,068, পরের বছরের বাসিন্দা কর ¥153,260, সামাজিক বিমা ¥527,400, বার্ষিক নিট ¥2,872,272 এবং মাসিক গড় ¥239,356 দেয়। এগুলো মডেলের ফল, নিশ্চিত বেতনপত্র নয়।" }, faq: { question: "জাপানে প্রকৃত হাতে-পাওয়া বেতন আলাদা হতে পারে কেন?", answer: "স্বাস্থ্যবিমায় 5% বিকল্প হার ব্যবহৃত; বিমাকারী/প্রদেশের হার, অবদানসীমা, বোনাস, নির্ভরশীল ও ব্যক্তিগত ছাড়, পৌরসভার পার্থক্য পুরোপুরি ধরা হয় না। ২০২৬ ছাড়তালিকার কার্যকর সময় এখনো মেলানো বাকি; এটিকে বর্তমান আইনি অঙ্ক ভাববেন না।" } },
    monthly: { description: "জাপানের মাসিক বেতনকে বার্ষিক করে বার্ষিক মডেল চালায়, তারপর কর্তন ও নিট আয় মাসিক গড় হিসেবে দেখায়। এটি নির্দিষ্ট মাসের বেতনপত্র নয়।", howTo: "মাসিক মোট বেতন লিখুন এবং বয়সের শ্রেণি বাছুন। ইঞ্জিন ১২ দিয়ে গুণ করে বার্ষিক মডেল প্রয়োগ করে ফল ১২ দিয়ে ভাগ করে। বোনাসের ইনপুট নেই, তাই বোনাস ধরা হয় না।", formula: "বার্ষিকীকৃত মোট = মাসিক বেতন × 12। বার্ষিক বেতন-ছাড়, বিমা ও কর মডেল প্রয়োগের পর প্রতিটি ফল 12 দিয়ে ভাগ করে ইয়েনে পূর্ণসংখ্যা করা হয়। 40+ বিকল্পে মডেল পরিচর্যা-বিমা যোগ হয়।", example: { question: "৪০ বছরের কম বয়সে মাসিক মোট ¥300,000 হলে কী ফল?", answer: "বার্ষিকীকৃত মোট ¥3,600,000। ইঞ্জিন মাসিক গড় আয়কর ¥3,922, বাসিন্দা কর ¥12,772, সামাজিক বিমা ¥43,950, মোট কর্তন ¥60,644 এবং মডেল নিট ¥239,356 দেখায়। বার্ষিক অনুমানকে ১২ মাসে ভাগ করা হয়েছে।" }, faq: { question: "বোনাস বা মাসভেদে পরিবর্তন ধরা হয়?", answer: "না। ধরা হয় একই বেতন ১২ মাস দেওয়া হয়েছে; বোনাস, প্রকৃত মাসিক অবদানভিত্তি, অঞ্চল, নির্ভরশীল বা বিমাকারীভেদে পার্থক্য গণনা হয় না। বার্ষিক মডেল ভাগ করা হয় এবং ইয়েন পূর্ণসংখ্যা করার কারণে সামান্য পার্থক্য হতে পারে।" } },
  },
  uk: {
    annual: { description: "Оцінює річну та середню місячну зарплату нетто в Японії, віднімаючи модельні податки й соціальне страхування від річного брутто. Це не офіційний індивідуальний розрахунковий лист.", howTo: "Введіть річну зарплату брутто та виберіть вік до 40 років або від 40. У варіанті 40+ додається модельний внесок на догляд; застосовуються налаштування сценарію 2026 року.", formula: "Трудовий дохід = річний оклад − зарплатне відрахування. Віднімаються модельне соцстрахування й базове відрахування для діапазону; оподатковувана база округлюється вниз до ¥1 000. Податок на доходи використовує задані прогресивні ставки та надбавку на відбудову. Податок резидента — спрощена оцінка на наступний рік. Річне нетто = брутто − страхування − обидва податки; місячне середнє = річне нетто ÷ 12.", example: { question: "Який результат для річного брутто ¥3 600 000 і віку до 40 років?", answer: "Розрахунок дає трудовий дохід ¥2 440 000, модельний податок ¥47 068, оцінку податку резидента наступного року ¥153 260, соцстрахування ¥527 400, річне нетто ¥2 872 272 та місячне середнє ¥239 356. Це результат моделі, а не гарантована відомість." }, faq: { question: "Чому фактична зарплата нетто в Японії може відрізнятися?", answer: "Для медичного страхування взято умовні 5%; тарифи страховика й префектури, ліміти внесків, бонуси, утриманці й особисті відрахування, а також муніципальні відмінності не враховані повністю. Дату застосування таблиці відрахувань 2026 року ще потрібно узгодити; не вважайте результат підтвердженою чинною сумою." } },
    monthly: { description: "Перераховує місячну зарплату в Японії на річну, застосовує річну модель і показує відрахування та нетто як середні за місяць. Це не відомість за конкретний місяць.", howTo: "Введіть місячну зарплату брутто та виберіть вікову групу. Розрахунок множить суму на 12, застосовує річну модель і ділить результати на 12. Бонуси не вводяться та не враховуються.", formula: "Річне брутто = місячна зарплата × 12. Застосовуються річні моделі відрахувань, страхування й податків; кожен результат ділять на 12 і округлюють до єни. Варіант 40+ додає річну модельну оцінку страхування догляду.", example: { question: "Який результат для місячного брутто ¥300 000 і віку до 40 років?", answer: "Річне брутто після перерахунку — ¥3 600 000. Середні за місяць: податок на доходи ¥3 922, податок резидента ¥12 772, соцстрахування ¥43 950, усі відрахування ¥60 644 і модельне нетто ¥239 356. Річну оцінку розподілено на 12 місяців." }, faq: { question: "Чи враховані бонуси або щомісячні зміни?", answer: "Ні. Вважається, що введена зарплата однакова всі 12 місяців; бонуси, фактична щомісячна база внесків і регіональні, сімейні чи страхові відмінності не обчислюються. Використовується спільна річна модель, округлення до єни може дати невелику різницю." } },
  },
  ms: {
    annual: { description: "Menganggarkan gaji bersih tahunan dan purata bulanan di Jepun dengan menolak cukai dan insurans sosial model daripada gaji kasar tahunan. Bukan pengiraan slip gaji rasmi individu.", howTo: "Masukkan gaji kasar tahunan dan pilih bawah 40 atau umur 40 tahun ke atas. Pilihan 40+ menambah proksi insurans penjagaan; andaian senario 2026 yang dikonfigurasi digunakan.", formula: "Pendapatan pekerjaan = gaji tahunan − potongan pendapatan gaji. Tolak insurans sosial model dan potongan asas yang berkenaan, kemudian bundarkan asas bercukai ke bawah kepada ¥1,000. Cukai pendapatan menggunakan jalur progresif konfigurasi serta surtaks pembinaan semula. Cukai penduduk ialah anggaran ringkas tahun hadapan. Bersih tahunan = kasar − insurans sosial − kedua-dua cukai; purata bulanan = bersih tahunan ÷ 12.", example: { question: "Apakah hasil untuk gaji kasar tahunan ¥3,600,000 dan umur bawah 40?", answer: "Enjin memberikan pendapatan pekerjaan ¥2,440,000, cukai pendapatan model ¥47,068, anggaran cukai penduduk tahun depan ¥153,260, insurans sosial ¥527,400, bersih tahunan ¥2,872,272 dan purata bulanan ¥239,356. Ini hasil model, bukan slip gaji terjamin." }, faq: { question: "Mengapa gaji bersih sebenar di Jepun boleh berbeza?", answer: "Insurans kesihatan menggunakan proksi 5%; perbezaan penanggung insurans/wilayah, had caruman, bonus, tanggungan dan potongan peribadi, serta perbezaan perbandaran tidak dimodelkan sepenuhnya. Tarikh pemakaian jadual potongan 2026 masih perlu diselaraskan; jangan anggap hasil ini amaun undang-undang semasa yang disahkan." } },
    monthly: { description: "Menukarkan gaji bulanan Jepun kepada tahunan, menggunakan model tahunan, kemudian memaparkan potongan dan bersih sebagai purata bulanan. Bukan slip gaji bagi bulan tertentu.", howTo: "Masukkan gaji kasar bulanan dan pilih kumpulan umur. Enjin mendarab dengan 12, menggunakan model tahunan dan membahagikan hasil dengan 12. Bonus tiada medan input dan tidak termasuk.", formula: "Kasar tahunan = gaji bulanan × 12. Model potongan gaji, insurans dan cukai tahunan digunakan; setiap hasil tahunan dibahagi 12 dan dibundarkan kepada yen. Pilihan 40+ menambah proksi insurans penjagaan tahunan.", example: { question: "Apakah hasil untuk gaji kasar bulanan ¥300,000 dan umur bawah 40?", answer: "Kasar tahunan ialah ¥3,600,000. Enjin memaparkan purata bulanan: cukai pendapatan ¥3,922, cukai penduduk ¥12,772, insurans sosial ¥43,950, jumlah potongan ¥60,644 dan bersih model ¥239,356. Anggaran tahunan dibahagikan kepada 12 bulan." }, faq: { question: "Adakah bonus atau perubahan bulanan disertakan?", answer: "Tidak. Gaji yang dimasukkan dianggap sama selama 12 bulan; bonus, asas caruman bulanan sebenar dan perbezaan wilayah, tanggungan atau penanggung insurans tidak dikira. Model tahunan yang sama digunakan dan pembundaran yen boleh menimbulkan sedikit perbezaan." } },
  },
  sv: {
    annual: { description: "Uppskattar årlig och genomsnittlig månatlig nettolön i Japan genom att dra modellerad skatt och socialförsäkring från årslönen brutto. Ingen officiell individuell lönespecifikation.", howTo: "Ange årslön brutto och välj under 40 eller 40 år och äldre. Valet 40+ lägger till modellens proxy för vårdförsäkring; de konfigurerade antagandena för 2026-scenariot används.", formula: "Arbetsinkomst = årslön − löneinkomstavdrag. Dra av modellerad socialförsäkring och grundavdrag för aktuell inkomstgrupp; skattebasen avrundas nedåt till ¥1 000. Inkomstskatten använder konfigurerade progressiva nivåer och återuppbyggnadstillägg. Invånarskatt är en förenklad uppskattning för nästa år. Årsnetto = brutto − socialförsäkring − båda skatterna; månadsmedel = årsnetto ÷ 12.", example: { question: "Vad ger ¥3 600 000 i årslön brutto för någon under 40?", answer: "Motorn ger arbetsinkomst ¥2 440 000, modellerad inkomstskatt ¥47 068, uppskattad invånarskatt nästa år ¥153 260, socialförsäkring ¥527 400, årsnetto ¥2 872 272 och månadsmedel ¥239 356. Det är modellresultat, ingen garanterad lönespecifikation." }, faq: { question: "Varför kan faktisk nettolön i Japan skilja sig?", answer: "Sjukförsäkringen använder en proxy på 5 %; skillnader mellan försäkringsgivare och prefekturer, avgiftstak, bonusar, anhöriga och personliga avdrag samt kommunala variationer modelleras inte fullt ut. När avdragsschemat för 2026 börjar gälla behöver fortfarande stämmas av; se inte resultatet som ett bekräftat aktuellt lagbelopp." } },
    monthly: { description: "Räknar upp japansk månadslön till ett år, använder årsmodellen och visar avdrag och netto som månadsgenomsnitt. Det är ingen lönespecifikation för en viss månad.", howTo: "Ange månadslön brutto och välj åldersgrupp. Motorn multiplicerar med 12, tillämpar årsmodellen och delar resultaten med 12. Bonus har inget inmatningsfält och räknas inte med.", formula: "Årsbrutto = månadslön × 12. Årliga modeller för avdrag, försäkring och skatt används; varje årsresultat delas med 12 och avrundas till yen. Valet 40+ lägger till vårdförsäkringens årliga proxy.", example: { question: "Vad ger ¥300 000 i månadslön brutto för någon under 40?", answer: "Årsbrutto blir ¥3 600 000. Motorn visar månatliga medel: inkomstskatt ¥3 922, invånarskatt ¥12 772, socialförsäkring ¥43 950, totala avdrag ¥60 644 och modellerat netto ¥239 356. Årsuppskattningen fördelas över tolv månader." }, faq: { question: "Ingår bonusar eller förändringar mellan månader?", answer: "Nej. Den angivna lönen antas vara densamma under alla tolv månader; bonus, faktiska månatliga avgiftsunderlag och regionala, familje- eller försäkringsskillnader beräknas inte. Samma årsmodell används och yenavrundning kan ge små skillnader." } },
  },
  cs: {
    annual: { description: "Odhaduje roční a průměrnou měsíční čistou mzdu v Japonsku odečtením modelovaných daní a sociálního pojištění od roční hrubé mzdy. Nejde o oficiální osobní výplatní pásku.", howTo: "Zadejte roční hrubou mzdu a zvolte věk do 40 let nebo od 40 let. Varianta 40+ přidá modelový odhad pojištění dlouhodobé péče; používají se nastavení scénáře 2026.", formula: "Příjem ze zaměstnání = roční mzda − odpočet příjmu ze mzdy. Odečte se modelované sociální pojištění a základní odpočet pro dané pásmo; základ daně se zaokrouhlí dolů na ¥1 000. Daň z příjmu používá nastavená progresivní pásma a rekonstrukční přirážku. Daň rezidenta je zjednodušeným odhadem na další rok. Roční čistá mzda = hrubá − pojištění − obě daně; měsíční průměr = roční čistá ÷ 12.", example: { question: "Jaký je výsledek při roční hrubé mzdě ¥3 600 000 a věku do 40 let?", answer: "Model vrací příjem ze zaměstnání ¥2 440 000, modelovou daň z příjmu ¥47 068, odhad daně rezidenta na příští rok ¥153 260, sociální pojištění ¥527 400, čistou roční mzdu ¥2 872 272 a měsíční průměr ¥239 356. Jde o výstup modelu, nikoli zaručenou výplatní pásku." }, faq: { question: "Proč se skutečná čistá mzda v Japonsku může lišit?", answer: "Zdravotní pojištění používá náhradní sazbu 5 %; plně se nemodelují rozdíly pojistitele a prefektury, limity příspěvků, bonusy, vyživované osoby a osobní odpočty ani rozdíly obcí. Datum použitelnosti odpočtů pro rok 2026 se ještě ověřuje; výsledek nepovažujte za potvrzenou aktuální zákonnou částku." } },
    monthly: { description: "Přepočítá japonskou měsíční mzdu na roční, použije roční model a zobrazí srážky i čistou mzdu jako měsíční průměry. Nejde o pásku za konkrétní měsíc.", howTo: "Zadejte měsíční hrubou mzdu a vyberte věkovou skupinu. Model částku násobí 12, použije roční výpočet a výsledky vydělí 12. Bonus nemá samostatný vstup a není zahrnut.", formula: "Roční hrubá mzda = měsíční mzda × 12. Použijí se roční modely odpočtů, pojištění a daní; každý roční výsledek se vydělí 12 a zaokrouhlí na jen. Volba 40+ přidá roční modelové pojištění péče.", example: { question: "Jaký je výsledek při měsíční hrubé mzdě ¥300 000 a věku do 40 let?", answer: "Roční přepočet činí ¥3 600 000. Model ukazuje měsíční průměr: daň z příjmu ¥3 922, daň rezidenta ¥12 772, sociální pojištění ¥43 950, celkové srážky ¥60 644 a modelovou čistou mzdu ¥239 356. Roční odhad je rozdělen do 12 měsíců." }, faq: { question: "Zahrnuje bonusy nebo změny mezi měsíci?", answer: "Ne. Zadaná mzda se předpokládá stejná po všech 12 měsíců; bonusy, skutečné měsíční základy odvodů a rozdíly podle oblasti, rodiny či pojistitele se nepočítají. Používá se stejný roční model a zaokrouhlení na jen může způsobit drobný rozdíl." } },
  },
  ro: {
    annual: { description: "Estimează salariul net anual și media lunară în Japonia scăzând impozitele și asigurările sociale modelate din brutul anual. Nu este un fluturaș oficial individual.", howTo: "Introduceți salariul brut anual și alegeți sub 40 de ani sau 40+. Opțiunea 40+ adaugă proxy-ul modelat pentru asigurarea de îngrijire; se folosesc ipotezele configurate pentru scenariul 2026.", formula: "Venit salarial = brut anual − deducerea salarială. Se scad asigurările sociale modelate și deducerea de bază aplicabilă, apoi baza impozabilă se rotunjește în jos la ¥1.000. Impozitul pe venit folosește tranșele progresive configurate și suprataxa de reconstrucție. Impozitul de rezidență este o estimare simplificată pentru anul următor. Net anual = brut − asigurări − ambele impozite; media lunară = net anual ÷ 12.", example: { question: "Ce rezultat apare la ¥3.600.000 brut anual și vârsta sub 40 de ani?", answer: "Motorul returnează venit salarial ¥2.440.000, impozit modelat ¥47.068, impozit de rezidență estimat pentru anul următor ¥153.260, asigurări sociale ¥527.400, net anual ¥2.872.272 și medie lunară ¥239.356. Sunt rezultate ale modelului, nu un fluturaș garantat." }, faq: { question: "De ce poate diferi netul real din Japonia?", answer: "Asigurarea de sănătate folosește un proxy de 5%; tarifele asigurătorului și prefecturii, plafoanele contribuțiilor, bonusurile, persoanele în întreținere și deducerile personale și diferențele municipale nu sunt modelate complet. Data de aplicare a deducerilor 2026 încă trebuie reconciliată; nu considerați rezultatul o sumă legală actuală confirmată." } },
    monthly: { description: "Annualizează salariul lunar japonez, aplică modelul anual și afișează reținerile și netul ca medii lunare. Nu reprezintă fluturașul unei luni anume.", howTo: "Introduceți salariul brut lunar și selectați grupa de vârstă. Motorul înmulțește cu 12, aplică modelul anual și împarte rezultatele la 12. Bonusurile nu au câmp de introducere și nu sunt incluse.", formula: "Brut anualizat = salariu lunar × 12. Se aplică modelul anual de deduceri, asigurări și impozite; fiecare rezultat anual se împarte la 12 și se rotunjește la yen. Opțiunea 40+ adaugă proxy-ul anual pentru asigurarea de îngrijire.", example: { question: "Ce rezultat apare la ¥300.000 brut lunar și vârsta sub 40 de ani?", answer: "Brutul anualizat este ¥3.600.000. Motorul afișează mediile lunare: impozit pe venit ¥3.922, impozit de rezidență ¥12.772, asigurări sociale ¥43.950, rețineri totale ¥60.644 și net modelat ¥239.356. Estimarea anuală este împărțită la 12 luni." }, faq: { question: "Sunt incluse bonusurile sau variațiile lunare?", answer: "Nu. Salariul introdus este presupus identic în toate cele 12 luni; bonusurile, bazele lunare reale ale contribuțiilor și diferențele regionale, familiale sau ale asigurătorului nu sunt calculate. Se folosește același model anual, iar rotunjirea la yen poate crea mici diferențe." } },
  },
  el: {
    annual: { description: "Εκτιμά το ετήσιο και μέσο μηνιαίο καθαρό εισόδημα στην Ιαπωνία αφαιρώντας μοντελοποιημένους φόρους και κοινωνική ασφάλιση από τον ετήσιο μικτό μισθό. Δεν είναι επίσημη ατομική μισθοδοσία.", howTo: "Εισαγάγετε τον ετήσιο μικτό μισθό και επιλέξτε κάτω των 40 ή 40 ετών και άνω. Η επιλογή 40+ προσθέτει την προσεγγιστική εισφορά φροντίδας του μοντέλου· χρησιμοποιούνται οι ρυθμισμένες παραδοχές σεναρίου 2026.", formula: "Εισόδημα εργασίας = ετήσιος μισθός − έκπτωση μισθωτής εργασίας. Αφαιρούνται η μοντελοποιημένη κοινωνική ασφάλιση και η βασική έκπτωση της κατηγορίας· η φορολογητέα βάση στρογγυλοποιείται προς τα κάτω στα ¥1.000. Ο φόρος εισοδήματος ακολουθεί τις ρυθμισμένες προοδευτικές κλίμακες και την πρόσθετη εισφορά ανασυγκρότησης. Ο φόρος κατοίκου είναι απλή εκτίμηση επόμενου έτους. Ετήσιο καθαρό = μικτό − ασφάλιση − οι δύο φόροι· μηνιαίος μέσος = ετήσιο καθαρό ÷ 12.", example: { question: "Τι αποτέλεσμα έχει ετήσιος μικτός μισθός ¥3.600.000 για ηλικία κάτω των 40;", answer: "Ο κινητήρας επιστρέφει εισόδημα εργασίας ¥2.440.000, μοντελοποιημένο φόρο εισοδήματος ¥47.068, εκτίμηση φόρου κατοίκου επόμενου έτους ¥153.260, κοινωνική ασφάλιση ¥527.400, ετήσιο καθαρό ¥2.872.272 και μηνιαίο μέσο ¥239.356. Είναι αποτέλεσμα μοντέλου, όχι εγγυημένο εκκαθαριστικό." }, faq: { question: "Γιατί μπορεί να διαφέρει ο πραγματικός καθαρός μισθός στην Ιαπωνία;", answer: "Η ασφάλιση υγείας χρησιμοποιεί υπόθεση 5%· οι διαφορές ασφαλιστή και νομού, τα όρια εισφορών, τα μπόνους, τα εξαρτώμενα μέλη και οι προσωπικές εκπτώσεις, καθώς και οι δημοτικές διαφορές δεν μοντελοποιούνται πλήρως. Η ημερομηνία εφαρμογής των εκπτώσεων 2026 εκκρεμεί προς συμφωνία· μην θεωρείτε το αποτέλεσμα επιβεβαιωμένο ισχύον νόμιμο ποσό." } },
    monthly: { description: "Αναγάγει τον μηνιαίο μισθό στην Ιαπωνία σε ετήσιο, εφαρμόζει το ετήσιο μοντέλο και εμφανίζει κρατήσεις και καθαρό ως μηνιαίους μέσους όρους. Δεν είναι εκκαθαριστικό συγκεκριμένου μήνα.", howTo: "Εισαγάγετε τον μηνιαίο μικτό μισθό και επιλέξτε ηλικιακή ομάδα. Ο κινητήρας πολλαπλασιάζει επί 12, εφαρμόζει το ετήσιο μοντέλο και διαιρεί τα αποτελέσματα με 12. Δεν υπάρχει πεδίο μπόνους, άρα δεν περιλαμβάνεται.", formula: "Ετησιοποιημένο μικτό = μηνιαίος μισθός × 12. Εφαρμόζεται ετήσιο μοντέλο εκπτώσεων, ασφάλισης και φόρων· κάθε ετήσιο αποτέλεσμα διαιρείται με 12 και στρογγυλοποιείται σε γιεν. Η επιλογή 40+ προσθέτει την ετήσια προσέγγιση ασφάλισης φροντίδας.", example: { question: "Τι αποτέλεσμα έχει μηνιαίος μικτός ¥300.000 για ηλικία κάτω των 40;", answer: "Το ετησιοποιημένο μικτό είναι ¥3.600.000. Ο κινητήρας εμφανίζει μηνιαίους μέσους όρους: φόρος εισοδήματος ¥3.922, φόρος κατοίκου ¥12.772, κοινωνική ασφάλιση ¥43.950, συνολικές κρατήσεις ¥60.644 και μοντελοποιημένο καθαρό ¥239.356. Η ετήσια εκτίμηση κατανέμεται σε 12 μήνες." }, faq: { question: "Περιλαμβάνονται μπόνους ή μηνιαίες μεταβολές;", answer: "Όχι. Θεωρείται ίδιος μισθός και στους 12 μήνες· μπόνους, πραγματικές μηνιαίες βάσεις εισφορών και διαφορές περιοχής, οικογένειας ή ασφαλιστή δεν υπολογίζονται. Χρησιμοποιείται το ίδιο ετήσιο μοντέλο και η στρογγυλοποίηση σε γιεν μπορεί να δημιουργήσει μικρή απόκλιση." } },
  },
};
